package org.eclipse.rdf4j.sail.lmdb;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.nio.file.Path;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

import org.eclipse.rdf4j.common.transaction.IsolationLevels;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.repository.sail.SailRepository;
import org.eclipse.rdf4j.sail.lmdb.config.LmdbStoreConfig;
import org.eclipse.rdf4j.sail.lmdb.model.LmdbValue;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.CleanupMode;
import org.junit.jupiter.api.io.TempDir;

class LmdbRetirementPinnedExplicitRecoveryTest {

	@Test
	void explicitRecoveryCannotReclaimAValueStillNeededByAnOldSnapshot(
			@TempDir(cleanup = CleanupMode.NEVER) Path directory) throws Exception {
		var config = new LmdbStoreConfig("spoc,posc,ospc").setForceSync(true)
				.setInlineLiterals(false)
				.setSketchEstimatorEnabled(false)
				.setDirectAdjacencyEnabled(false)
				.setValueOverlayEnabled(false);
		LmdbStore store = new LmdbStore(directory.toFile(), config);
		SailRepository repository = new SailRepository(store);
		var writer = Executors.newSingleThreadExecutor();
		try {
			repository.init();
			LmdbTestUtil.awaitPostReadyInitialization(store, 30, TimeUnit.SECONDS);
			var vf = SimpleValueFactory.getInstance();
			var subject = vf.createIRI("urn:retirement-pinned:subject");
			var predicate = vf.createIRI("urn:retirement-pinned:predicate");
			var object = vf.createIRI("urn:retirement-pinned:object");
			try (var connection = repository.getConnection()) {
				connection.begin(IsolationLevels.NONE);
				connection.add(subject, predicate, object);
				connection.commit();
			}
			LmdbSailStore backing = store.getBackingStore();
			ValueStore values = backing.valueStore();
			long id = values.getId(subject);
			assertTrue(id != LmdbValue.UNKNOWN_ID);
			try (LmdbSailStore.DatasetAdmission old = backing.beginDatasetAdmission(IsolationLevels.SNAPSHOT_READ,
					null)) {
				writer.submit(() -> {
					try (var connection = repository.getConnection()) {
						connection.begin(IsolationLevels.NONE);
						connection.remove(subject, predicate, object);
						connection.commit();
					}
				}).get(30, TimeUnit.SECONDS);
				var before = values.pollRetiredIds(Long.MAX_VALUE, 64);
				assertNotNull(before);
				assertTrue(before.ids.contains(id), "the old snapshot must leave the removed owner in the queue");
				assertEquals(id, values.getId(old.view().valueSnapshot(), subject));
				backing.recoverRetiredValueIds();
				assertEquals(id, values.getId(subject),
						"explicit recovery must not reclaim while the old snapshot remains pinned");
				var after = values.pollRetiredIds(Long.MAX_VALUE, 64);
				assertNotNull(after, "the blocked retirement must stay durable");
				assertTrue(after.ids.contains(id));
			}
		} finally {
			writer.shutdownNow();
			assertTrue(writer.awaitTermination(30, TimeUnit.SECONDS));
			repository.shutDown();
		}
	}
}
